  "q2_target_disease": {
    "answer": "No",
    "evidence": "Title and description: 'Gene expression patterns in peripheral blood correlate with the extent of coronary artery disease' and repeated references to coronary artery disease (CAD) and CAD index (CADi).",
    "justification": "The study focuses on coronary artery disease (CAD), not amyotrophic lateral sclerosis or frontotemporal dementia (ALS-FTD)."
  },
  "q3_human_cns_tissue": {
    "answer": "No",
    "evidence": "Description: 'Gene expression profile in circulating leukocytes' and samples are peripheral blood leukocytes; Organism: Homo sapiens; Organism part: not CNS.",
    "justification": "Samples are circulating leukocytes (peripheral blood), not human brain or CNS tissue."
  },
  "q4_non_clinical": {
    "answer": "No",
    "evidence": "Description and samples indicate RNA extracted from patients undergoing coronary angiography (110 patients with CAD and 112 controls); no mention of cell lines or disease models.",
    "justification": "The study uses primary patient blood samples rather than patient-derived in vitro cell lines or experimental disease models."
  },
  "q5_case_control_design": {
    "answer": "Yes",
    "evidence": "Description: RNA was extracted from 110 patients with CAD (CADi>23) and from 112 partially matched controls without CAD (CADi=0); 'parallel group design'.",
    "justification": "There are defined case and control groups (CAD patients versus controls), consistent with a case/control design."
  },
  "q6_irrelevant_brain_region": {
    "answer": "Yes",
    "evidence": "Samples are circulating leukocytes (peripheral blood), not brain regions; Organism part: not CNS.",
    "justification": "The tissue sampled (peripheral blood) is not a brain region and is not relevant to ALS-FTD neurodegeneration."
  },
  "q7_incompatible_technology": {
    "answer": "No",
    "evidence": "Study type: transcription profiling by array; Affymetrix U133A chips; Technology: Array assay; Assay by Molecule: RNA assay.",
    "justification": "The technology is microarray-based expression profiling, which is compatible with inclusion criteria."
  },
  "q8_inclusion_justification": {
    "justification": "Exclude. Although the dataset is human microarray expression profiling and has a case/control design, it does not pertain to ALS-FTD and does not use CNS brain tissue (samples are peripheral blood leukocytes). It therefore fails the disease and tissue inclusion criteria."
  },
  "q9_include_dataset": {
    "answer": "No"
  }
}

